#include "titan_theme_scene_graph.h"
#include <string.h>
void TitanThemeScene_Init(TitanThemeCompiledScene *s){if(s)memset(s,0,sizeof(*s));}
int TitanThemeScene_AddLayer(TitanThemeCompiledScene *s,const TitanThemeCompiledLayer *l){if(!s||!l||s->layer_count>=TITAN_THEME_SCENE_MAX_LAYERS)return 0;s->layers[s->layer_count]=*l;s->layers[s->layer_count].declaration_order=s->layer_count;s->layer_count++;return 1;}
static int After(const TitanThemeCompiledLayer*a,const TitanThemeCompiledLayer*b){return a->z_order>b->z_order||(a->z_order==b->z_order&&a->declaration_order>b->declaration_order);}
void TitanThemeScene_StableSort(TitanThemeCompiledScene*s){unsigned int i,j;if(!s)return;for(i=1;i<s->layer_count;i++){TitanThemeCompiledLayer key=s->layers[i];j=i;while(j>0&&After(&s->layers[j-1],&key)){s->layers[j]=s->layers[j-1];j--;}s->layers[j]=key;}}
void TitanThemeScene_MarkDirty(TitanThemeCompiledLayer*l,uint32_t f){if(l)l->dirty_flags|=f;}
void TitanThemeScene_ClearDirty(TitanThemeCompiledLayer*l,uint32_t f){if(l)l->dirty_flags&=~f;}

static uint32_t ThemeRand(uint32_t *s){*s=*s*1664525u+1013904223u;return *s;}
int TitanThemeTimeline_Validate(const TitanThemeTimeline*t){unsigned int i;if(!t||t->declared_count==0u||t->declared_count>TITAN_THEME_MAX_DECLARED_FRAMES)return 0;for(i=0;i<t->declared_count;i++)if(t->frames[i].duration_ms<TITAN_THEME_FRAME_DURATION_MIN_MS||t->frames[i].duration_ms>TITAN_THEME_FRAME_DURATION_MAX_MS)return 0;return 1;}
void TitanThemeTimeline_Reset(TitanThemeTimeline*t,uint32_t seed){if(!t)return;t->elapsed_ms=0;t->direction=1;t->deterministic_seed=seed?seed:1u;t->current_index=0u;if(t->declared_count&&t->mode==TITAN_THEME_TIMELINE_RANDOM_START)t->current_index=ThemeRand(&t->deterministic_seed)%t->declared_count;}
static void Advance(TitanThemeTimeline*t){unsigned int n=t->declared_count;if(n<2u)return;if(t->mode==TITAN_THEME_TIMELINE_HOLD)return;if(t->mode==TITAN_THEME_TIMELINE_RANDOM_SEQUENCE){t->current_index=ThemeRand(&t->deterministic_seed)%n;return;}if(t->mode==TITAN_THEME_TIMELINE_PINGPONG){if(t->direction>0&&t->current_index+1u>=n)t->direction=-1;else if(t->direction<0&&t->current_index==0u)t->direction=1;t->current_index=(unsigned int)((int)t->current_index+t->direction);return;}if(t->current_index+1u<n)t->current_index++;else if(t->mode==TITAN_THEME_TIMELINE_LOOP||t->mode==TITAN_THEME_TIMELINE_RANDOM_START)t->current_index=0u;}
void TitanThemeTimeline_Update(TitanThemeTimeline*t,uint32_t d){if(!TitanThemeTimeline_Validate(t))return;t->elapsed_ms+=d;while(t->elapsed_ms>=t->frames[t->current_index].duration_ms){t->elapsed_ms-=t->frames[t->current_index].duration_ms;Advance(t);if(t->mode==TITAN_THEME_TIMELINE_ONCE&&t->current_index+1u>=t->declared_count){t->elapsed_ms=0u;break;}}}
void TitanThemeTimeline_PlanResidency(const TitanThemeTimeline*t,TitanThemeResidency*r){int next,recent;if(!r)return;r->current=r->next=r->recent=-1;r->resident_count=0u;if(!t||!t->declared_count)return;r->current=(int)t->current_index;r->resident_count=1u;if(t->declared_count==1u)return;next=(int)t->current_index+(t->direction<0?-1:1);if(next<0)next=(int)t->declared_count-1;if(next>=(int)t->declared_count)next=0;r->next=next;r->resident_count++;if(t->declared_count>2u){recent=(int)t->current_index-(t->direction<0?-1:1);if(recent<0)recent=(int)t->declared_count-1;if(recent>=(int)t->declared_count)recent=0;r->recent=recent;r->resident_count++;}}

int TitanThemeBudget_CanReserveVram(const TitanThemeBudget*b,uint32_t used,uint32_t req,uint32_t total){uint64_t end;if(!b)return 0;end=(uint64_t)used+req+b->reserved_headroom;if(end>total)return 0;if((uint64_t)used+req>b->vram_budget)return 0;return 1;}
void TitanThemeStream_Init(TitanThemeStreamQueue*q){if(q)memset(q,0,sizeof(*q));}
int TitanThemeStream_Request(TitanThemeStreamQueue*q,uint32_t id,uint32_t bytes,uint8_t pri){TitanThemeStreamRequest*r;if(!q||!id||!bytes||q->count>=TITAN_THEME_STREAM_QUEUE_CAPACITY)return 0;r=&q->requests[q->write_index];r->asset_id=id;r->bytes=bytes;r->priority=pri;r->valid=1u;q->write_index=(q->write_index+1u)%TITAN_THEME_STREAM_QUEUE_CAPACITY;q->count++;return 1;}
int TitanThemeStream_Pop(TitanThemeStreamQueue*q,TitanThemeStreamRequest*out){TitanThemeStreamRequest*r;if(!q||!out||!q->count)return 0;r=&q->requests[q->read_index];*out=*r;memset(r,0,sizeof(*r));q->read_index=(q->read_index+1u)%TITAN_THEME_STREAM_QUEUE_CAPACITY;q->count--;return 1;}
int TitanThemeAtlas_ValidateRegion(const TitanThemeAtlasRegion*r){if(!r||!r->asset_id||!r->width||!r->height)return 0;if((uint32_t)r->x+r->width>r->atlas_width||(uint32_t)r->y+r->height>r->atlas_height)return 0;return 1;}
static float Norm(float v){return v<-1.0f?-1.0f:(v>1.0f?1.0f:v);}
float TitanThemeParallax_Offset(const TitanThemeCompiledLayer*l,const TitanThemeParallaxInput*i){if(!l||!i)return 0.0f;return l->parallax*(Norm(i->navigation)*0.40f+Norm(i->focus)*0.25f+Norm(i->transition)*0.25f+Norm(i->idle)*0.10f);}
void TitanThemeDynamic_ApplyPressure(TitanThemeDynamicBudget*b,unsigned int p){if(!b)return;if(p>=85u){b->quality=TITAN_THEME_QUALITY_REDUCED;b->spawn_budget/=4u;b->update_budget/=2u;b->draw_budget/=2u;}else if(p>=65u){b->quality=TITAN_THEME_QUALITY_BALANCED;b->spawn_budget/=2u;b->update_budget=(b->update_budget*3u)/4u;b->draw_budget=(b->draw_budget*3u)/4u;}else b->quality=TITAN_THEME_QUALITY_FULL;if(b->draw_budget>b->max_particles)b->draw_budget=b->max_particles;}
